// ============================================================================
// BACKEND CONNECTION
// Leave API_BASE_URL empty to run frontend-only (plans are generated locally).
// When the backend is ready, set it to e.g. 'http://localhost:4000'.
// ============================================================================
// Backend (FastAPI) default: 'http://localhost:8000'. Empty = fully local mode.
const API_BASE_URL = 'http://localhost:8000';

async function apiGet(path) {
  const res = await fetch(`${API_BASE_URL}${path}`);
  if (!res.ok) throw new Error(`GET ${path} -> ${res.status}`);
  return res.json();
}

async function apiPost(path, body) {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!res.ok) throw new Error(`POST ${path} -> ${res.status}`);
  return res.json();
}

// Server generates + saves the farm model; returns { id, createdAt, model } (or null if offline mode)
async function submitFarmerProfile(payload) {
  if (!API_BASE_URL) return null;
  return apiPost('/api/farmer-profiles', payload);
}

