// ============================================================================
// WEATHER HELPERS (WMO CODE DECODER & FALLBACK FORECAST)
// ============================================================================
function decodeWeatherCode(code) {
  if (code === 0) return { label: 'Clear Sky', icon: 'sun' };
  if ([1, 2, 3].includes(code)) return { label: 'Partly Cloudy', icon: 'cloud-sun' };
  if ([45, 48].includes(code)) return { label: 'Misty / Foggy', icon: 'cloud' };
  if ([51, 53, 55, 61, 63, 65, 80, 81, 82].includes(code)) {
    return { label: 'Rain Showers', icon: 'rain' };
  }
  if ([95, 96, 99].includes(code)) return { label: 'Thunderstorm', icon: 'rain' };
  return { label: 'Fair Weather', icon: 'cloud-sun' };
}

function WeatherIcon({ type, className = 'w-6 h-6' }) {
  if (type === 'sun') return <Sun className={`${className} text-amber-500`} />;
  if (type === 'rain') return <CloudRain className={`${className} text-sky-500`} />;
  if (type === 'cloud') return <Cloud className={`${className} text-slate-400`} />;
  return <CloudSun className={`${className} text-amber-500`} />;
}

function buildFallbackWeather(district) {
  const days = ['Today', 'Tomorrow', 'Day 3', 'Day 4', 'Day 5'];
  return {
    isFallback: true,
    district,
    current: {
      temp: 29,
      humidity: 56,
      windSpeed: 11,
      rainProb: 20,
      condition: decodeWeatherCode(1)
    },
    daily: days.map((day, idx) => ({
      day,
      maxTemp: 30 + (idx % 3) - 1,
      minTemp: 19 + (idx % 2),
      rainProb: idx === 2 ? 45 : 15 + idx * 5,
      condition: decodeWeatherCode(idx === 2 ? 61 : idx % 2 === 0 ? 0 : 2)
    }))
  };
}

function getFarmingAdvisory(temp, rainProb) {
  if (rainProb >= 60) {
    return {
      level: 'Rain Alert',
      tone: 'bg-sky-50 border-sky-200 text-sky-900',
      badge: 'bg-sky-600 text-white',
      message:
        'High chance of rainfall ahead. Pause scheduled drip irrigation, clear field drainage channels, and delay foliar fertilizer spraying.'
    };
  }
  if (temp >= 35) {
    return {
      level: 'Heat Advisory',
      tone: 'bg-amber-50 border-amber-200 text-amber-900',
      badge: 'bg-amber-600 text-white',
      message:
        'Elevated daytime temperatures detected. Schedule drip irrigation during early morning or sunset hours and apply organic straw mulching to reduce evaporation.'
    };
  }
  return {
    level: 'Favorable Field Window',
    tone: 'bg-green-50 border-green-200 text-green-900',
    badge: 'bg-[#69BD01] text-white',
    message:
      'Ideal agro-climatic conditions for sowing, weeding, composting, and precision irrigation. Keep soil moisture between 55% and 75% for optimal root health.'
  };
}

